export function download(name,text,type='application/json'){const u=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
export function csv(samples){const keys=['lat','lng','time','leg','speed','heading','azimuth','elevation','shipRelative','cameraRelative','opticalAngle','inFov'];return '\ufeff'+keys.join(',')+'\r\n'+samples.map(s=>keys.map(k=>k==='time'?new Date(s[k]).toISOString():s[k]).join(',')).join('\r\n');}
export function geojson(p,r){return {type:'FeatureCollection',features:[...r.legs.map(l=>({type:'Feature',geometry:{type:'LineString',coordinates:[[l.a.lng,l.a.lat],[l.b.lng,l.b.lat]]},properties:{speed_kt:l.speed,heading:l.heading}})),...r.samples.map(s=>({type:'Feature',geometry:{type:'Point',coordinates:[s.lng,s.lat]},properties:{...s,time:new Date(s.time).toISOString()}}))]};}
